import { motion } from 'framer-motion';
import { FadeUp } from './Reveal';

const reviews = [
  {
    quote:
      'The pacing in Thani Kaattu Raja gave me chills. Genuinely feels like a theatre release, not a YouTube short.',
    name: 'Karthik R.',
    role: 'Subscriber',
  },
  {
    quote:
      'Aval Naan Mazhai is proof that you don\u2019t need a big budget to make people cry. Beautiful, honest filmmaking.',
    name: 'Divya S.',
    role: 'Film Student',
  },
  {
    quote:
      'Every release keeps getting sharper. The lighting and sound design punch way above their weight.',
    name: 'Aravind M.',
    role: 'Indie Creator',
  },
];

export const Testimonials = () => {
  return (
    <section className="px-6 md:px-12 py-28 md:py-40 bg-[#0a0a0a] border-y border-white/10">
      <FadeUp>
        <span className="text-[11px] tracking-[0.3em] uppercase text-[#E11D48]">[ Word on the street ]</span>
        <h2 className="font-display font-semibold text-5xl md:text-7xl uppercase leading-[0.95] mt-5 max-w-3xl">
          What the audience says
        </h2>
      </FadeUp>

      <div className="mt-16 grid grid-cols-1 md:grid-cols-3 gap-px bg-white/10">
        {reviews.map((r, i) => (
          <motion.blockquote
            key={r.name}
            initial={{ opacity: 0, y: 40 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true, margin: '-60px' }}
            transition={{ duration: 0.8, delay: i * 0.12, ease: [0.16, 1, 0.3, 1] }}
            className="bg-[#0a0a0a] p-8 md:p-12 flex flex-col justify-between min-h-[320px]"
          >
            <span className="font-display text-[#E11D48] text-6xl leading-none">&ldquo;</span>
            <p className="font-serif-italic text-2xl md:text-3xl leading-snug text-white/90 -mt-6">
              {r.quote}
            </p>
            <footer className="mt-8 pt-6 border-t border-white/10">
              <div className="text-sm font-medium">{r.name}</div>
              <div className="text-[11px] tracking-[0.2em] uppercase text-white/40 mt-1">{r.role}</div>
            </footer>
          </motion.blockquote>
        ))}
      </div>
    </section>
  );
};
